def maximum_uncrossed_lines(nums1, nums2):
 dp=[0]*(len(nums2)+1)
 for x in nums1:
  previous=0
  for j,y in enumerate(nums2,1):
   saved=dp[j];dp[j]=previous+1 if x==y else max(dp[j],dp[j-1]);previous=saved
 return dp[-1]

